float4 mayaCreatePointShadowMapPS( float3 lightPosition, float3 Pw, float2 range)		
{																						
   float3 LightToVertex = Pw - lightPosition;											
   float LightToPixelDistance = (length(LightToVertex)-range.x) / (range.y-range.x);	
	return float4(LightToPixelDistance, 0.0, 0.0, LightToPixelDistance);				
}


float4 mayaCreatePointShadowMapPS( float3 lightPosition, float3 Pw, float2 range)		
{																						
   float3 LightToVertex = Pw - lightPosition;											
   float LightToPixelDistance = (length(LightToVertex)-range.x) / (range.y-range.x);	
	return float4(LightToPixelDistance, 0.0, 0.0, LightToPixelDistance);				
}


